/*
 * Host microcontroller sketch: load the trained model into the chip and run it.
 *
 * The four pin functions at the top are placeholders. On the Tiny Tapeout demo
 * board (RP2040) or with an FPGA you would implement them with GPIO writes and
 * reads. Everything below them is plain C that follows SPEC.md.
 */
#include <stdint.h>
#include <stdio.h>
#include "bnn_weights.h"   // generated by model/export.py

// ---- Board-specific: replace these with real GPIO code ----
void set_ui_in(uint8_t v);       // drive the 8 data pins
void set_uio_in(uint8_t v);      // drive the mode pins (uio_in[1:0])
void clock_pulse(void);          // one full clock cycle: high, then low
uint8_t read_uo_out(void);       // read the 8 output pins
void set_rst_n(int level);

// Put a byte on the pins with a given mode, then clock it in.
static void send(uint8_t mode, uint8_t data) {
    set_uio_in(mode);
    set_ui_in(data);
    clock_pulse();
}

void bnn_reset(void) {
    set_rst_n(0);
    for (int i = 0; i < 5; i++) clock_pulse();
    set_rst_n(1);
}

// Send the configuration bitstream from bnn_weights.h (SPEC.md section 5).
void bnn_load_model(void) {
    for (unsigned i = 0; i < sizeof(bnn_bitstream); i++)
        send(bnn_bitstream_modes[i], bnn_bitstream[i]);
}

// Run one input byte through the neuron. Returns y; writes popcount to *pc.
int bnn_infer(uint8_t x, uint8_t *pc) {
    send(BNN_MODE_RUN, x);
    uint8_t out = read_uo_out();
    if (pc) *pc = (out >> 1) & 0x0F;
    return out & 1;
}

int run_demo(void) {
    bnn_reset();
    bnn_load_model();
    for (int x = 0; x < 256; x++) {
        uint8_t pc;
        int y = bnn_infer((uint8_t)x, &pc);
        printf("x=0x%02X pc=%u y=%d\n", x, pc, y);
    }
    return 0;
}
